from collections import deque,Counter

def comp_labels(g, line, signals):
 H=len(g);W=len(g[0]); seen=set(); comps=[]
 for r in range(H):
  for c in range(W):
   if g[r][c] in signals and (r,c) not in seen:
    q=[(r,c)];seen.add((r,c));comp=[]
    while q:
     p=q.pop();comp.append(p)
     for dr,dc in [(1,0),(-1,0),(0,1),(0,-1)]:
      z=(p[0]+dr,p[1]+dc)
      if 0<=z[0]<H and 0<=z[1]<W and g[z[0]][z[1]] in signals and z not in seen:seen.add(z);q.append(z)
    comps.append(comp)
 return comps

def line_dist_from_clusters(g,line,signals):
