 # labels by majority signal color; compute multi-source distances from all cluster cells to all line cells; distances through line cells + signals in same comp (we can seed adjacent line cells at distance 0)
 # Distances across line graph only; each seed's adjacent line cells are source starts.
 preds={}
 for idx,cp in enumerate(cps):
  counts=Counter(g[r][c] for r,c in cp); lab=counts.most_common(1)[0][0]
  starts=[]
  for r,c in cp:
   for dr,dc in [(1,0),(-1,0),(0,1),(0,-1)]:
    z=(r+dr,c+dc)
    if 0<=z[0]<H and 0<=z[1]<W and g[z[0]][z[1]]==line: starts.append(z)
  # shortest dist from starts in line graph
  d={p:0 for p in set(starts)};q=deque(d)
  while q:
   p=q.popleft()
   for dr,dc in [(1,0),(-1,0),(0,1),(0,-1)]:
    z=(p[0]+dr,p[1]+dc)
    if 0<=z[0]<H and 0<=z[1]<W and g[z[0]][z[1]]==line and z not in d:
     d[z]=d[p]+1;q.append(z)
  for p,v in d.items():
   preds.setdefault(p,[]).append((v,idx,lab))
